1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	
7	import net.officefloor.plugin.variable.Out;
8	import net.officefloor.plugin.variable.Val;
9	import org.springframework.samples.petclinic.mapper.OwnerMapper;
10	import org.springframework.samples.petclinic.model.Owner;
11	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
12	import org.springframework.samples.petclinic.repository.OwnerRepository;
13	
14	public class BuildOwner {
15	
16	    public void service(@Val OwnerFieldsDto request, @Val Household.Id householdId,
17	            OwnerMapper ownerMapper, OwnerRepository ownerRepository, Out<Owner> built) {
18	        Owner owner = ownerMapper.toOwner(request);
19	        // The effective registration date defaults an unsupplied value to the server's
20	        // current date, then rolls any weekend forward to the next Monday so derived values
21	        // (e.g. the membership number's year) use the adjusted business day.
22	        owner.setRegistrationDate(BusinessDay.effectiveRegistrationDate(owner.getRegistrationDate()));
23	        owner.setCustomerCode(customerCode(owner));
24	        // Record how many existing owners already share this first+last name (case-insensitive),
25	        // counted before this owner is persisted so the value is fixed at creation time.
26	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName(), ownerRepository));
27	        // Join a shared household when the gate resolved an identifier.
28	        if (householdId != null && householdId.isPresent()) {
29	            owner.setHouseholdId(householdId.value());
30	        }
31	        // Record the household's member count (existing members plus this not-yet-persisted
32	        // owner) so the membership points rule can score a household of 3 or more.
33	        owner.setHouseholdSize(Household.size(owner.getHouseholdId(), ownerRepository) + 1);
34	        built.set(owner);
35	    }
36	
37	    /**
38	     * Build the '<REGION>-<HASH8>' customer code: REGION is the region derived from the owner's
39	     * postcode and city ({@link Owner#regionFor(String, String)}, e.g. 'NSW' or 'UNKNOWN'), and
40	     * HASH8 is the first 8 upper-case hex characters of the SHA-256 of the normalized telephone
41	     * followed by the last name (e.g. 'NSW-1A2B3C4D'). There is no sequence number, so the code
42	     * is stable for an owner regardless of creation order.
43	     */
44	    private static String customerCode(Owner owner) {
45	        String region = Owner.regionFor(owner.getPostcode(), owner.getCity());
46	        String normalizedTelephone = OwnerTelephone.normalize(owner.getTelephone());
47	        String seed = (normalizedTelephone == null ? "" : normalizedTelephone) + owner.getLastName();
48	        return region + "-" + hash8(seed);
49	    }
50	
51	    /**
52	     * The first 8 upper-case hex characters of the SHA-256 of the UTF-8 bytes of {@code seed}.
53	     */
54	    private static String hash8(String seed) {
55	        try {
56	            byte[] digest = MessageDigest.getInstance("SHA-256")
57	                    .digest(seed.getBytes(StandardCharsets.UTF_8));
58	            StringBuilder sb = new StringBuilder(8);
59	            for (int i = 0; i < 4; i++) {
60	                sb.append(String.format("%02X", digest[i]));
61	            }
62	            return sb.toString();
63	        }
64	        catch (NoSuchAlgorithmException ex) {
65	            throw new IllegalStateException("SHA-256 not available", ex);
66	        }
67	    }
