38	     * Whether {@code email}'s domain is on the disposable-domain blocklist. Expects an address
39	     * already shown to be syntactically valid (so it contains a single {@code @}); the domain is
40	     * the part after the {@code @}, matched case-insensitively.
41	     */
42	    static boolean isDisposableDomain(String email) {
43	        if (email == null) {
44	            return false;
45	        }
46	        int at = email.lastIndexOf('@');
47	        if (at < 0) {
48	            return false;
49	        }
50	        return DISPOSABLE_DOMAINS.contains(email.substring(at + 1).toLowerCase());
51	    }
