53	    /** Lower-case and trim the email, or {@code null} when absent/blank. */
54	    static String normalize(String email) {
55	        if (email == null) {
56	            return null;
57	        }
58	        String trimmed = email.trim();
59	        return trimmed.isEmpty() ? null : trimmed.toLowerCase();
60	    }
